# v3: v2 with fuel savings aimed at the ~24 suspended (lost) turns per game. Behaviour is
# otherwise unchanged.
# - The altar ring is computed once and reused while no visible altar is locked, instead of
#   rescanning the map every carrying turn.
# - respawning_visible_spawns() and enemies_visible() are computed once per turn.
# - Dashes in travel and the opener are skipped when fuel is low, so a heavy turn ends with
#   a cheap walk instead of being suspended.

# ---- tunable constants ----
CLEAR_POWER = 60
HURT_FRAC = 0.5
RETREAT_FRAC = 0.3
GEM_RETREAT_FRAC = 0.5
BAG_MIN = 20
LATE_ROUND = 1500
OPEN_FRAC = 0.8
OPEN_FRAC_HURT = 0.6
FOCUS_FRAC = 0.5
RICH_SLACK = 4
FUEL_GUARD = 30000
# fuel needed before attempting a dash (dash_towards is expensive on big maps)
DASH_FUEL = 45000
THREAT_RANGE = 6

# ---- macros ----
def fight(t):
    if health() < HURT_FRAC * max_health():
        if ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)):
            cast_self(0)
        elif ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)):
            cast_self(1)
    if ability_ready(0) and slot_is_stun(0):
        cast_at_unit(0, t)
    elif ability_ready(1) and slot_is_stun(1):
        cast_at_unit(1, t)
    if ability_ready(0) and not slot_is_shield(0) and not slot_is_dash(0) and not slot_is_heal(0) and not slot_is_reset(0):
        cast_at_unit(0, t)
    if ability_ready(1) and not slot_is_shield(1) and not slot_is_dash(1) and not slot_is_heal(1) and not slot_is_reset(1):
        cast_at_unit(1, t)
    if i_am_ranged() and distance( unit_position(t), position() ) <= 1 and can_move():
        move_away_from( unit_position(t) )
        end_turn()
    attack(t)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
        attack(t)
    elif ability_ready(1) and slot_is_reset(1):
        cast_self(1)
        attack(t)
    end_turn()

def open_with(s, foe):
    if slot_is_dash(s):
        dash_towards(s, unit_position(foe))
    else:
        cast_at_unit(s, foe)
    set_team_target(foe)
    if distance( position(), unit_position(foe) ) <= 1 or (i_am_ranged() and distance( position(), unit_position(foe) ) <= 3):
        attack(foe)
    else:
        move_towards( unit_position(foe) )
    end_turn()

def can_open(s, d):
    return ability_ready(s) and (slot_stun(s) > 0 or (slot_is_damage(s) and not slot_is_dash(s))) and d <= slot_range(s) + slot_radius(s) and (fuel_remaining() > DASH_FUEL or not slot_is_dash(s))

def go(t):
    if fuel_remaining() > DASH_FUEL:
        if ability_ready(0) and slot_is_dash(0):
            dash_towards(0, t)
        elif ability_ready(1) and slot_is_dash(1):
            dash_towards(1, t)
