        end_turn()

let inrange = filter( enemies_visible(), in_attack_range() )
let enemy = weakest( inrange )

# opener: nobody in basic reach, but an enemy is within a stun/damage ability's reach
if not exists(enemy) and gems() < BAG_MIN and fuel_remaining() > FUEL_GUARD:
    let foe = nearest( enemies_visible() )
    if exists(foe):
        let fd = distance( position(), unit_position(foe) )
        if health() >= OPEN_FRAC * max_health():
            if can_open(0, fd):
                open_with(0, foe)
            elif can_open(1, fd):
                open_with(1, foe)
        elif health() >= OPEN_FRAC_HURT * max_health():
            # hurt: only a stun opener, so the enemy is locked before it closes
            if ability_ready(0) and slot_stun(0) > 0 and fd <= slot_range(0) + slot_radius(0):
                open_with(0, foe)
            elif ability_ready(1) and slot_stun(1) > 0 and fd <= slot_range(1) + slot_radius(1):
                open_with(1, foe)
        elif unit_health_frac(foe) < FOCUS_FRAC:
            # healthy but the enemy is already hurt: stun it before it can retreat or heal
            if ability_ready(0) and slot_stun(0) > 0 and fd <= slot_range(0) + slot_radius(0):
                open_with(0, foe)
            elif ability_ready(1) and slot_stun(1) > 0 and fd <= slot_range(1) + slot_radius(1):
                open_with(1, foe)

# finisher: a badly hurt enemy just outside basic reach is dashed onto before it can heal
if exists(enemy) and fuel_remaining() > FUEL_GUARD and unit_health_frac(enemy) < FINISH_FRAC:
    let fin_d = distance( position(), unit_position(enemy) )
    if ability_ready(0) and slot_is_dash(0) and fin_d <= slot_range(0) + 1:
        dash_towards(0, unit_position(enemy))
        end_turn()
    elif ability_ready(1) and slot_is_dash(1) and fin_d <= slot_range(1) + 1:
        dash_towards(1, unit_position(enemy))
        end_turn()

