        go( gem_target )
    else:
        move_towards( near_camp )
else:
    if exists(gem_target):
        go( gem_target )
    else:
        move_towards( near_camp )

let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
# healthier champions act first next round; a wounded one acts later and can retreat or
# finish a target with the team's focus
set_priority( 1 + floor( 100 * health() / max_health() ) )
end_turn()

